function showDraft(){const grid=$('#upgradeGrid');grid.innerHTML='';const choices=[...upgrades].sort(()=>Math.random()-.5).slice(0,6);for(const item of choices){const i=upgrades.indexOf(item),el=document.createElement('button');el.className='upgrade-card';el.style.setProperty('--upgrade-color',item[2]==='WEAPON'?'#ff9b72':item[2]==='VITALS'?'#d5fa43':'#8de1e0');el.innerHTML=`<div class="card-top"><span class="upgrade-icon">${item[0]}</span><span class="upgrade-type">${item[2]}</span></div><h3>${item[1]}</h3><p>${item[3]}</p><span class="pick-tag">TAKE THIS ↗</span>`;el.onclick=()=>chooseUpgrade(i);grid.append(el)}show('draft')}
