function sendNet(data){try{if(state.conn?.open)state.conn.send(data)}catch(e){console.warn('Network send failed',e)}}
function onlineMessage(msg){if(!msg||!msg.t)return;
 if(msg.t==='input'&&state.onlineRole==='host'){state.remoteInput=msg;return}
 if(msg.t==='start'&&state.onlineRole==='join'){state.roundsToWin=msg.rounds;state.mapsInMatch=msg.maps;startGame();return}
 if(msg.t==='state'&&state.onlineRole==='join'){player.x=msg.e.x;player.y=msg.e.y;player.angle=msg.e.a;player.hp=msg.e.hp;player.maxHp=msg.e.maxHp;state.playerScore=msg.e.score;enemy.x=msg.p.x;enemy.y=msg.p.y;enemy.angle=msg.p.a;enemy.hp=msg.p.hp;enemy.maxHp=msg.p.maxHp;state.enemyScore=msg.p.score;state.round=msg.round;if(msg.arena!==state.arenaIndex)setArena(msg.arena);return}
 if(msg.t==='round'&&state.onlineRole==='join'){state.playerScore=msg.es;state.enemyScore=msg.ps;roundSummary(msg.winner==='player'?'enemy':'player');return}
 if(msg.t==='pick'){const target=state.onlineRole==='host'?enemy:enemy;applyUpgrade(target,msg.i);if(state.onlineRole==='host'&&state.localPicked===false&&state.screen==='roundEnd')startNextRound();return}
 if(msg.t==='next'&&state.onlineRole==='join'){state.localPicked=false;state.round++;if((state.round-1)%Math.max(1,state.mapsInMatch)===0)setArena(state.round-1);resetRound();return}
 if(msg.t==='finish'&&state.onlineRole==='join'){state.playerScore=msg.es;state.enemyScore=msg.ps;finishMatch();return}
}
function connectEvents(conn,role){state.conn=conn;state.onlineRole=role;conn.on('open',()=>{$('#connectionStatus').textContent='PEER CONNECTED · '+(role==='host'?'WAITING FOR MATCH START':'READY TO PLAY');$('#onlineNotice').textContent='CONNECTED — '+(role==='host'?'YOU CAN START THE MATCH':'WAITING FOR YOUR FRIEND TO START');state.connected=true;if(role==='host')$('#startMatch').disabled=false});conn.on('data',onlineMessage);conn.on('close',()=>{$('#connectionStatus').textContent='CONNECTION LOST';$('#onlineNotice').textContent='CONNECTION LOST — RECONNECT TO CONTINUE';state.connected=false;if(state.screen==='game')notify('CONNECTION LOST')});conn.on('error',e=>{$('#onlineNotice').textContent='CONNECTION ERROR · TRY A NEW ROOM';console.error(e)})}
