async function joinPeerRoom(){const code=$('#roomInput').value.trim();if(!code){$('#onlineNotice').textContent='ENTER A ROOM CODE FIRST';return}const btn=$('#joinRoom');btn.disabled=true;btn.textContent='CONNECTING…';$('#onlineNotice').textContent='CONNECTING TO HOST…';try{await loadPeer();state.peer=new Peer();state.peer.on('open',()=>{const conn=state.peer.connect(code,{reliable:true});connectEvents(conn,'join')});state.peer.on('error',e=>{$('#onlineNotice').textContent=`NETWORK ERROR: ${e.type||'CHECK THE ROOM CODE'}`;btn.disabled=false;btn.textContent='JOIN ROOM ↗'})}catch(e){$('#onlineNotice').textContent='ONLINE CONNECTION UNAVAILABLE — CHECK YOUR INTERNET';btn.disabled=false;btn.textContent='JOIN ROOM ↗'}}
